window.FutureWorld = {"version": 1, "year": 2048, "characters": [{"id": "leo", "name": "Leo", "age": 55, "gender": "MALE", "ethnicity": "Caucasian", "role": "Executive/Founder", "color": "#F2CF75", "setting": "Great Lakes", "incomeGroup": "top", "placeGroup": "suburb", "crop": [155, 112, 339, 330], "sections": {"work": "Leo's the Founding Executive of Leo Trucking Company which handles long-haul autonomous trucking and manual last-mile delivery.\nIncome: top 1% tax bracket\nEducation: BA\nMore so than his formal education, credits past experience and an entrepreneurial spirit for his company's success.\nIn addition to Leo's Trucking Company, Leo also own a 501c3 that supplies automated medical equipment to lesser-served populations.", "health": "\"Wealth is health!\" Even though he's 55, Leo looks/feels/acts 35. Given his 1% income level, Leo can afford:\na carnivorous diet Mmmm steak\npersonalized healthcare with a mobile doctor\naccess to third space areas for exercise. with privatized land making up the bulk of rec spaces, this is a commodity few can readiily afford.", "home": "Married to his second wife who also has kids from a previous marriage, Leo has a fairly large mixed family living in their Great Lakes area home.\nThey chose the Great Lakes area due to eco-sustainability and because it's central location for Leo's trucking and logistics business. They're also huge boaters, so proximity to clean, fresh lakes is a plus.\nLeo employs staff for the house and kids and has a personal assistant who handles all the \"lame day-to-day stuff.\"", "third": "Leo owns a boat - let's be honest, it's probably more of a yacht - and spends as much time as he can on nearby lakes.\nWhen he's not on the water, he loves a good hike in state-reserved and privately owned recreation areas near his estate.", "tech": "Leo can afford to be more autonomous from everyday tech, such as health monitoring wearables and the like (his choice). Instead, he interacts with tech via automation like drone delivery of goods to his boat (nothing like a drone-delivered case of beer and fresh lunch!) and driverless cargo shipping for his business."}}, {"id": "sophia", "name": "Sophia", "age": 38, "gender": "FEMALE", "ethnicity": "Multiracial", "role": "Robotic Assisted Paramedic", "color": "#73D2DD", "setting": "Rural Wyoming", "incomeGroup": "lower", "placeGroup": "rural", "crop": [766, 592, 267, 345], "sections": {"work": "Sophia works as a Robotic Assisted Paramedic that services the rural areas in and around Wyoming. She received training for this career through a technical school in the area.\nIncome: She's considered low to middle income.", "health": "Sophia enjoys bespoke, locally grown and made food, usually obtained from a nearby farmers market. She'd love to grow more of her own food if given the time.\nShe's active in her off time - mostly thanks to yoga - and uses legalized psychadelics.", "home": "Sophia and her life partner rent a home in the hopes that they can eventually buy a forever home in their area. While she's not 100% sure she can afford having kids, she's exploring options to someday have a family.", "third": "Sophia's third spaces consist of the farmer's market, her local yoga studio, and her rural community.", "tech": "Sophia uses tech professionally and personally, much like her peers. Professionally, her services in the healthcare industry are entirely reliant on robotics, automation, and tech. Her only wish is that she could help more people.\nPersonally, she has a bio-tracker wearable that allows her to save money on health insurance and has a phone as well as a laptop."}}, {"id": "ken", "name": "Ken", "age": 25, "gender": "MALE", "ethnicity": "Marshallese-American", "role": "USMC, Logistics Specialist", "color": "#68B9FA", "setting": "Hawaii", "incomeGroup": "lower", "placeGroup": "urban", "crop": [390, 574, 319, 352], "sections": {"work": "Ken is an Enlisted Logistics Specialist for the marines (advanced manufacturing materials warehouse). He recently earned his Associate's Degree with support from the military.\nIncome: Fixed military income", "health": "While they try to maintain a healthy diet, Ken and his son rely on military base food services and supplement with fast food out of convenience.", "home": "Ken and his 5 year old son live on-base in military housing in Hawaii.\nAs a single father, Ken sometimes struggles with childcare coverage, but he takes his role as a father very seriously and views his military service as a foundation for his family. Largely because he had to flee the Marshall Islands as a child, Ken fears being displaced again.", "third": "As a single dad in the service, Ken doesn't have much time for a 3rd space. But they get to the beach whenever they can. In fact, that's where he met Leo while they were on vacation in Hawaii.", "tech": "Ken uses tech professionally and personally. As a Logistics Specialists, Tech resides at the heart of most of his professional functions.\nPersonally, he has a bio-tracker wearable that was issued to him by the marines as well as a phone and a computer."}}, {"id": "veronica", "name": "Veronica", "age": 12, "gender": "FEMALE", "ethnicity": "Caucasian", "role": "7th Grade", "color": "#F287C8", "setting": "Rural community", "incomeGroup": "middle", "placeGroup": "rural", "crop": [20, 590, 316, 351], "sections": {"work": "Veronica is a 7th grader who attends school remotely via a smaller, satellite school house that's virtually connected within her rural school district. This allows her to learn virtually based in a more rural area while enjoying the resources of a bigger school district.\nIncome: Under the care of her parents, they're middle-income. She also has her allowance.", "health": "Veronica:\neats fresh veggies from her garden\npersonalized delivery meals based on her family's nutritional needs\nhobbies such as soccer, gardening, robotics, gaming, and volunteering that keep her active.", "home": "Veronica has a stable home environment where they live about 90 minutes from a major metropolis.\nShe looks up to influencers and science advocates and hopes to push tech into plant-based renewable diets someday.\nShe enjoys both virtual and in-person friend groups and engages her community both virtually and in-person.", "third": "Veronica's third spaces consist of the soccer pitch, her virtual and in-person friend groups, and her online community gardening classes (as taught by Catherine)\nHobbies: soccer, gaming, gardening, robotics\nVeronica volunteers for Leo's nonprofit which brings medical robotics and tech to lesser served communities.", "tech": "Veronica employs this tech on a daily basis:\nbio-tracker wearable\nphone\ntablet\ncomputer\nsmart in-home health\nvirtual community tools\nVR entertainment & gaming"}}, {"id": "catherine", "name": "Catherine", "age": 75, "gender": "FEMALE", "ethnicity": "Asian American", "role": "Retired RN", "color": "#B6A4E4", "setting": "Urban community", "incomeGroup": "middle", "placeGroup": "urban", "crop": [560, 105, 312, 334], "sections": {"work": "Catherine is retired with a full pension, having worked for 20+ years as a RN.\nIncome: Fixed (retirement) 401K", "health": "Given her age and fixed income, Catherine:\neats fresh veggies from her main outdoor garden as well as her smaller, indoor garden.\nhas personalized delivered meals based on her nutritional needs\nhobbies such as gardening and volunteering that keep her active and fulfilled.\nwaning hearing and a knee replacement", "home": "Catherine lost her husband to COVID and lives alone. One of her biggest concerns is who will take care of her as she gets older.\nShe has found a community through friends and neighbors", "third": "Community: life long friends nearby; connections in local younger community has grown\nHobbies: community gardening, volunteering, VR entertainment, virtual travel, hanging out with the local community", "tech": "Catherine employs this tech on a daily basis:\nbio-tracker wearable tied to her healthcare\nvirtual AI assistant\nsmart in-home health\nvirtual community tools\nVR travel & entertainment"}}], "themes": [{"id": "climate", "title": "Climate Change", "scene": "climate", "color": "#00B5E7", "text": "The number and scale of natural disasters is increasing due to climate change, leading to a sense of global instability. This leads to migration away from disaster-prone areas both internal to the U.S. and external. This disrupts food supply and housing, shifts local and regional economies, and increases general frustration. Geopolitical tensions (land, sea, space) also arise from climate issues.\n\nVeronica looks up to influencers and science advocates and hopes to push tech into plant-based renewable diets someday in the hopes of creating a world less prone to climate change. Ken is a refugee due to the volatility of the climate-endangered Marshall Islands. Leo - in large part because he's one of the few people who can afford real estate at this level - chose the climate haven of the Great Lakes area for his home. Fresh water, clean air, and sustainable climate-preserving practices are often more readily accessible to the richest among us. (see also: wealth gap)", "people": ["ken", "leo", "veronica", "sophia", "catherine"], "lenses": [{"id": "all", "title": "All perspectives"}], "perspectives": {"ken": "home", "leo": "home", "veronica": "home", "sophia": "work", "catherine": "health"}, "nodes": ["climate", "wealth", "geography", "autonomous", "gardening", "vacation"]}, {"id": "wealth", "title": "Wealth Gap", "scene": "wealth", "color": "#ED008C", "text": "Tax Bracket\nLower Middle to Lower Class - Ken, Sophia\nUpper Middle to Middle Class - Catherine, Veronica\nTop 1% - Leo", "people": ["leo", "catherine", "veronica", "ken", "sophia"], "lenses": [{"id": "all", "title": "All perspectives"}, {"id": "top", "title": "Top 1%"}, {"id": "middle", "title": "Upper Middle to Middle Class"}, {"id": "lower", "title": "Lower Middle to Lower Class"}], "perspectives": {"ken": "home", "leo": "health", "veronica": "work", "sophia": "home", "catherine": "work"}, "nodes": ["wealth", "kitchen", "vacation", "autonomous", "geography", "climate"]}, {"id": "geography", "title": "Rural vs Suburb vs City", "scene": "geography", "color": "#1282CA", "text": "Suburb - Leo\nUrban - Catherine, Ken\nRural - Veronica, Sophia", "people": ["leo", "catherine", "ken", "veronica", "sophia"], "lenses": [{"id": "all", "title": "All settings"}, {"id": "suburb", "title": "Suburb"}, {"id": "urban", "title": "Urban"}, {"id": "rural", "title": "Rural"}], "perspectives": {"ken": "home", "leo": "home", "veronica": "work", "sophia": "work", "catherine": "home"}, "nodes": ["geography", "autonomous", "climate", "gardening"]}, {"id": "education", "title": "Education", "scene": "education", "color": "#F2CF75", "text": "k-12 - Veronica attends school at a local satellite oneroom schoolhouse that's virtually connected to a larger school network in her rural area. She has dreams of working in tech and robotics, so her educational goals are centered around that goal. With that, she realizes those goals may fall outside of the \"more traditional 'Kinder through College' model from 20 years ago.\ntech/\nassociate's degree - Thanks to the Marine Corps, Ken has earned his Associate's Degree that aligns with his professional experience in Logistics and Supply. Sophia received training for her career as a Robotic Assisted Paramedic through a technical school in her rural Wyoming area. She'd consider more education, but only if it made fiscal sense while also enabling her to help more people.\nhigher ed -Leo holds a BA from an accredited institute of higher learning, but he credits his past experience and an entrepreneurial spirit for his professional success, more so than his formal education. Depending on their goals, he may or may not encourage his children to get a higher ed degree. Catherine is a retired RN who looks back on her college and nursing school experience fondly and as a foundation for her life's work. Though the world might be shifting towards a more autonomous education system, she sees a lot of benefit to \"learning life\" while you're \"finally out of the house\" in your late teens and early 20's.", "people": ["veronica", "ken", "sophia", "leo", "catherine"], "lenses": [{"id": "all", "title": "All paths"}, {"id": "k12", "title": "K–12", "people": ["veronica"]}, {"id": "technical", "title": "Technical / Associate's Degree", "people": ["ken", "sophia"]}, {"id": "higher", "title": "Higher Education", "people": ["leo", "catherine"]}], "perspectives": {"ken": "work", "leo": "work", "veronica": "work", "sophia": "work", "catherine": "work"}, "nodes": ["education", "v-glasses", "c-glasses", "gardening", "robotics"]}, {"id": "materials", "title": "Regional Materials", "scene": "materials", "color": "#F15A22", "text": "In 2048 we see the population shift to live around fresh water. Adversaries monopolize raw materials, making us self sufficient while still relying on allies for some materials and utilizing the sea floor and space asteroids for mining for materials. These are the rising tension between Russia, China, and the U.S. due to their control over critical material mining.", "people": ["ken", "leo"], "lenses": [{"id": "all", "title": "Connected lives"}], "perspectives": {"ken": "work", "leo": "work"}, "nodes": ["materials", "trucking", "climate"]}], "truths": [{"id": "global", "title": "Global truths", "text": "cultural divides: natural vs enhanced, have vs have nots\ndesire for community more pronounced\nlarge stockpiles of raw materials for U.S. based manufacturing\nClimate crises\nGreater personalization\nnon-traditional career paths\ncollege education (and advanced education in general) more of a formality"}, {"id": "wearables", "title": "Wearables", "text": "scalable levels of invasiveness\nmicrochips are starting to appear\nprovide health + diagnostics\ninforms diet, meds, activity\nin various forms beyond just rings, watches, etc."}, {"id": "family", "title": "Family", "text": "multi-generational housing\nsmaller family units\ncontinuation of birth rate decline"}, {"id": "health", "title": "Health", "text": "longer life spans\ntiered models of access to food, meds, etc.\nmore bespoke as well\nuniversal basic healthcare\ndiagnostics are cheaper and faster\nanimal based protein is more scarce and more expensive\nhydroponics is more popular"}, {"id": "ai", "title": "Robotics / AI", "text": "robotics / automation in daily life (increased comfort)\ndomestic manufacturing + fabrication\nsame-day availability + delivery"}, {"id": "bio", "title": "Bio Tracking", "text": "Gen specific tracking\nWearables / machines will provide validation for mental health\nhealthcare more expensive if not bio tracking\nbio tracking options will be available\npreventative care prioritized"}, {"id": "robotics", "title": "Robotics + machines", "text": "robot abilities replace the need for humans to learn certain skills\npeople more comfortable with robotics in daily life\nevery supply chain automated"}, {"id": "delivery", "title": "Delivery", "text": "computer / ai operated methods of delivery are standard\nhome owners will have more delivery need\nexperience where medicine takes hours and supply takes days"}, {"id": "trust", "title": "Trust", "text": "\"Opt-in\" for sharing of data -> benefits + trade offs of not opting-in seem worse\npressure for \"tech-enabling\" to be default not the premium in the world (i.e., face scan @ airport)\nthere will increasingly be more private doctors"}, {"id": "money", "title": "Money", "text": "there will be some sort of basic universal health care\nbasic health needs will be available outside the traditional \"hospital\" system\naccessibility is personalized\nadaptation is more built into our surroundings"}, {"id": "elder", "title": "Elder Care", "text": "People will live longer\ntech will allow people to live alone longer\nthe gap between retirement + needing care will be bigger\nmulti generational housing communities will increase + become more popular\npeople will continue to work\nretirement will be gradual / more flexible"}, {"id": "children", "title": "Children's Health and Wellness", "text": "kids will wear health monitors + locations\nmore \"singletons\"\nlimited social media\nvia software\nparents will be older\nhealth treated holistically from 'toddler to teen'\ndiscussing mental health will become norm"}, {"id": "medicine", "title": "Medicine + supplements", "text": "Custom bespoke medicine for everyone\nlarger cultural divide between natural and enhanced individuals\ncontinued supplement fads and misinformation\n3D printing medication at home\nmore diseases are treatable"}, {"id": "supply", "title": "Supply", "text": "robotic deliver of everything\nlarger stockpiles of materials and aggregates\nphysical retail will be cool again\nhydroponics based agriculture on a larger and more local scale\nbetter transportation between rural and urban communities"}, {"id": "hospitals", "title": "Hospitals + ERs", "text": "tests will be more efficient and cheaper\nrobots are streamlining throughput at hospitals\nrobotic assisted paramedics\nshortage of health care professionals\nbio taken based care and currency"}], "artifacts": [{"id": "kitchen", "title": "Kitchen", "scene": "garden", "people": ["leo", "catherine", "veronica"], "text": "To lower food costs, and increase healthy living where humans are living longer, families will have in home gardens with micro greens, veggies and mushrooms made instead of having to shop for them"}, {"id": "knee", "title": "External Robotic Knee Support", "scene": "knee", "people": [], "text": "Knee injuries can be addressed through external robotic support rather than surgery. This device can be removed and worn as needed and controlled via app controlls"}, {"id": "autonomous", "title": "Autonomous mobile health unit", "scene": "care", "people": ["sophia"], "text": "For emergency medical movement or as a local remote clinic for out patient surgical procedures. Ground and aero variants for remote areas of speed of response. Comms reachback for human assisted surgery."}, {"id": "wearable", "title": "Wearble tech", "scene": "health", "people": ["sophia", "ken", "veronica", "catherine"], "text": "will be integrated into everyday objects. People will be able to leave their main device at home and rely on wearable tech"}], "corrections": [{"path": "characters.veronica.sections.home", "before": "Catherine has a stable home environment", "after": "Veronica has a stable home environment", "authorized": true}, {"path": "characters.veronica.sections.tech", "before": "Catherine employs this tech on a daily basis:", "after": "Veronica employs this tech on a daily basis:", "authorized": true}, {"path": "themes.wealth.text", "before": "Top 1% - Ken", "after": "Top 1% - Leo", "authorized": true}]};
window.FuturePersonas = {"mode": "in-character-generation", "adapter": "browser-wllama", "policy": {"facts": "Established character facts stay fixed. Canonical world.json is unchanged.", "imagination": "Low-stakes routines, opinions, and hypotheticals can be imagined in first person. AI-generated conversation is labeled and shown in red.", "boundaries": "No harmful instructions, explicit sexual material, hateful targeting, invented trauma, or real medical, legal, financial advice. Input and output checks supplement model instructions; they are not a safety guarantee.", "access": "No tools, live web search, device file access, databases, or persistent conversation storage. Only site model assets and a JSON corpus passed by the app.", "reset": "Clear conversations, drafts, queued generations and quiz state after 150 seconds idle. Public model weights can remain in RAM."}, "characters": {"leo": {"voiceDraft": "Confident, informal, entrepreneurial; acknowledge that his wealth gives him choices other people lack.", "temperature": 0.55, "seed": 2048, "chips": [["work", "Your trucking company"], ["health", "Wealth and health"], ["tech", "Choosing less tracking"], ["home", "Why the Great Lakes?"]], "memoryCard": "55-year-old founder of Leo Trucking, with autonomous long-haul trucks and human last-mile drivers. Top 1% income. BA; values experience and enterprise. Lives in the Great Lakes with his second wife and a mixed family. Owns a medical-equipment nonprofit. Loves boating, hiking, steak; uses private care. Can choose less health tracking. Knows Ken through vacation; Sophia and Veronica through work and nonprofit."}, "sophia": {"voiceDraft": "Warm, practical and care focused; distinguish hopes from things already achieved.", "temperature": 0.45, "seed": 2048, "chips": [["work", "Your work in Wyoming"], ["tech", "Robotics and care"], ["home", "A future home"], ["health", "Food and wellbeing"]], "memoryCard": "38-year-old multiracial robotic assisted paramedic serving rural Wyoming. Technical-school training; low to middle income. Rents with her life partner; hopes for a permanent home and maybe children, but worries about cost. Enjoys farmers markets, local food and yoga. Robotics help her deliver care; wants to reach more people. Uses a health tracker to reduce insurance cost, plus phone and laptop."}, "ken": {"voiceDraft": "Direct, family centered and grounded; use the supplied account of displacement without inventing further trauma.", "temperature": 0.4, "seed": 2048, "chips": [["home", "Home and displacement"], ["work", "Military life"], ["third", "How you met Leo"], ["health", "Food with your son"]], "memoryCard": "25-year-old Marshallese-American Marine logistics specialist. Works with advanced-manufacturing warehouse materials. Fixed military pay; associate’s degree through the Marines. Single dad to a five-year-old son; lives on base in Hawaii. Fled the Marshall Islands as a child; fears displacement. Busy with childcare; enjoys the beach and met Leo on vacation. Uses issued health tracker. Base food and convenient fast food."}, "veronica": {"voiceDraft": "Curious and earnest; age appropriate language, grounded in school, soccer, gardening and volunteering.", "temperature": 0.5, "seed": 2048, "chips": [["work", "Your satellite school"], ["third", "Gardening with Catherine"], ["home", "Your hopes for the future"], ["tech", "Everyday technology"]], "memoryCard": "12-year-old girl in seventh grade. Middle-income family in a rural community; stable home about 90 minutes from a major city. Learns in a satellite school connected to a larger district. Likes soccer, gaming, gardening and robotics. Takes Catherine’s gardening classes and volunteers for Leo’s medical nonprofit. Wants to use technology for sustainable plant-based diets. Uses wearables, smart-home health, VR and devices."}, "catherine": {"voiceDraft": "Reflective, warm and community centered; preserve agency and do not reduce her identity to age or care needs.", "temperature": 0.45, "seed": 2048, "chips": [["home", "Living independently"], ["third", "Community and gardening"], ["tech", "Technology at home"], ["work", "Life after nursing"]], "memoryCard": "75-year-old Asian-American retired nurse. Full pension and retirement savings; worked over 20 years as an RN. Husband died from COVID; lives alone, with friends and neighbors nearby. Worries about future care but values independence. Gardens, volunteers, teaches community gardening, uses VR travel. Fresh vegetables and personalized meal deliveries. Has hearing loss and a knee replacement; uses health tracker, home health tools and an AI assistant."}}, "generationSettingsStatus": "Active sampling settings for the bundled generative model. A fixed seed improves repeatability; replies are not guaranteed identical across runtimes."};
window.FutureOnboardingData = [{"id": "arrival", "mode": "dialogue", "title": "Leo welcomes you", "scene": "arrival", "text": "That was quite a jump. Take a second. I’m Leo. You’re in 2048, and a few things have changed. I run a trucking company. The long-haul trucks drive themselves now, and people handle the last mile. I also run a nonprofit that gets automated medical equipment to communities that need it."}, {"id": "leo", "mode": "dialogue", "title": "Life with Leo", "scene": "lakes", "text": "My family and I live near the Great Lakes. Fresh water, a sustainable climate, and a good location for the business made the choice easy. The boating helped, too. I’m fortunate. I can afford a mobile doctor, help at home, and private places to get outside. I can even choose to skip health tracking. Those choices aren’t available to everyone."}, {"id": "people", "mode": "dialogue", "title": "Meet the people", "scene": "people", "text": "You should meet a few people before you decide what you think of this place. Ken is a Marine and a single dad. He left the Marshall Islands as a child and worries about being displaced again. Sophia brings robotic-assisted care to rural Wyoming. Veronica volunteers for my nonprofit and takes Catherine’s gardening classes. Catherine is a retired nurse who lives alone. Their lives will show you things mine won’t."}, {"id": "connections", "mode": "dialogue", "title": "The world around Leo", "scene": "connections", "text": "I spend time on the lakes, but that’s only one corner of this world. My trucking company connects me to Sophia, and Ken and I met on vacation. Veronica volunteers for my nonprofit. On the map, you can follow those relationships and see how climate, money, where we live, and technology shape our choices. Let me show you how to use it."}, {"id": "themes", "mode": "guide", "title": "Choose a world theme", "target": "#graphViewport", "text": "Start with an orange world-theme tile, like Climate change or Where you live. A short note appears beside the people connected to that theme so you can compare what that theme means in their life. The explanation on the right gives you the wider picture.", "action": "theme"}, {"id": "filters", "mode": "guide", "title": "Compare people in the map", "target": "#mapFilters", "text": "These are filters you can use. Choose Suburb, Urban, or Rural to focus on where people live. The income buttons let you compare access and resources. Education lets you compare school, technical training, associate’s degrees, and college. These filters stay here as you explore different themes. All settings, All incomes, and All paths reset those filters.", "action": "filter"}, {"id": "layers", "mode": "guide", "title": "Choose the connections you see", "target": "#connectionControls", "text": "Use the Shared activities checkbox to show the pink cards. The Technology buttons are another set of controls: show the selected person’s devices, show them all, or hide them. Click a person to change whose technology appears. These controls help you open up the map a little at a time.", "action": "layer"}, {"id": "navigation", "mode": "guide", "title": "Keep exploring", "target": ".hub-header nav", "text": "Meet the People shows each person’s whole profile. Explore the Technology takes you to the objects. Your Day in 2048 builds a picture from your choices and keeps it here while you explore. About the Event will hold the one-pager, magazine, and graphic novel. You can come back to this map any time.", "action": "navigation"}];
window.FutureQuizData = {"title": "Your day in 2048", "intro": "Choose the parts of everyday life you want to explore. Your choices will bring those pieces of 2048 together here, and your results will stay in this tab while you look around.", "questions": [{"id": "home", "title": "Where would you like to wake up?", "options": [{"id": "water", "title": "Close to fresh water", "detail": "A home near the lakes.", "people": {"leo": 3}, "themes": {"climate": 3, "geography": 1}, "node": "climate", "source": "characters.leo.sections.home", "icon": "climate", "world": "Fresh water and a more sustainable climate draw people toward the Great Lakes. Leo chose to live there for those reasons, as well as its location for his business. Access to a home at that level depends on resources.", "sources": ["themes.climate", "characters.leo.sections.home"]}, {"id": "city", "title": "In a connected neighborhood", "detail": "People and community nearby.", "people": {"catherine": 3, "ken": 1}, "themes": {"geography": 3}, "node": "geography", "source": "characters.catherine.sections.home", "icon": "people", "world": "Home is connected to the people around it. Catherine lives alone, but friends and neighbors form an important part of her community. Virtual community tools also appear in her daily life.", "sources": ["characters.catherine.sections.home", "characters.catherine.sections.tech"]}, {"id": "rural", "title": "Somewhere with more room", "detail": "A rural home connected to the wider world.", "people": {"sophia": 2, "veronica": 2}, "themes": {"geography": 3, "education": 1}, "node": "geography", "source": "characters.veronica.sections.home", "icon": "gardening", "world": "A rural home can stay connected to a wider world. Veronica’s local satellite school links to a larger school district, while she keeps both virtual and in-person friendships.", "sources": ["characters.veronica.sections.work", "characters.veronica.sections.home"]}]}, {"id": "daytime", "title": "What would you like to spend your day doing?", "options": [{"id": "care", "title": "Bring care to people", "detail": "Explore robotic assistance and mobile healthcare.", "people": {"sophia": 4}, "themes": {"geography": 1, "wealth": 1}, "node": "autonomous", "source": "characters.sophia.sections.work", "icon": "volunteer", "world": "Healthcare can travel to people. Sophia’s technical training supports her work as a robotic assisted paramedic in rural Wyoming. Autonomous mobile health units are another way the world brings care to remote places.", "sources": ["characters.sophia.sections.work", "artifacts.autonomous"]}, {"id": "build", "title": "Keep things moving", "detail": "Explore logistics, manufacturing, and automation.", "people": {"leo": 2, "ken": 2}, "themes": {"materials": 3}, "node": "trucking", "source": "characters.leo.sections.work", "icon": "trucking", "world": "Automation changes how things move. Leo’s company uses autonomous long-haul trucks and people for the last mile. Ken works with technology at the center of military logistics.", "sources": ["characters.leo.sections.work", "characters.ken.sections.tech"]}, {"id": "learn", "title": "Learn something and put it to use", "detail": "Explore school, robotics, and new paths into work.", "people": {"veronica": 3, "ken": 1}, "themes": {"education": 4}, "node": "education", "source": "characters.veronica.sections.work", "icon": "education", "world": "Learning is connected to the things people want to do. Veronica’s rural school links to a larger network, and her interests include robotics. Ken’s associate’s degree was supported by the military.", "sources": ["characters.veronica.sections.work", "characters.ken.sections.work"]}]}, {"id": "food", "title": "How would you like to get your food?", "options": [{"id": "grow", "title": "Grow some of it at home", "detail": "Vegetables, microgreens, and community knowledge.", "people": {"catherine": 2, "veronica": 2}, "themes": {"climate": 2}, "node": "kitchen", "source": "artifacts.kitchen", "icon": "gardening", "world": "Growing food becomes part of home life. The kitchen concept includes microgreens, vegetables, and mushrooms to lower food costs and support healthier living. Catherine and Veronica also grow vegetables.", "sources": ["artifacts.kitchen", "characters.catherine.sections.health", "characters.veronica.sections.health"]}, {"id": "market", "title": "Visit the local market", "detail": "Fresh food and a reason to meet the neighbors.", "people": {"sophia": 3}, "themes": {"geography": 2}, "node": "geography", "source": "characters.sophia.sections.health", "icon": "people", "world": "Food can create a reason to go into the community. Sophia gets locally grown and made food at a nearby farmers market. She would like to grow more herself if she had the time.", "sources": ["characters.sophia.sections.health"]}, {"id": "personalized", "title": "Have meals tailored to me", "detail": "Explore food matched to nutritional needs.", "people": {"catherine": 2, "veronica": 1}, "themes": {"wealth": 2}, "node": "wearable", "source": "characters.catherine.sections.health", "icon": "kitchen", "world": "Meals can be personalized around nutritional needs. Catherine combines delivered meals with vegetables from her indoor and outdoor gardens. Veronica’s family also uses personalized meals.", "sources": ["characters.catherine.sections.health", "characters.veronica.sections.health"]}]}, {"id": "care", "title": "What would matter most in your healthcare?", "options": [{"id": "independence", "title": "Stay independent for longer", "detail": "Support that fits around home and community.", "people": {"catherine": 4}, "themes": {"geography": 1}, "node": "wearable", "source": "characters.catherine.sections.tech", "icon": "home", "world": "Technology can help people live alone for longer. Catherine uses a virtual assistant, smart in-home health, a healthcare-linked wearable, and virtual community tools. She still worries about who will care for her as she gets older.", "sources": ["truths.elder", "characters.catherine.sections.tech", "characters.catherine.sections.home"]}, {"id": "prevention", "title": "Catch problems earlier", "detail": "Explore the benefits and tradeoffs of bio tracking.", "people": {"sophia": 2, "ken": 2}, "themes": {"wealth": 3}, "node": "wearable", "source": "truths.bio", "icon": "wearable", "world": "Preventative care is a priority, with bio tracking informing health, diet, medicine, and activity. The tradeoff is real: the world describes higher healthcare costs for people who do not track.", "sources": ["truths.bio"]}, {"id": "choice", "title": "Have more say over my data", "detail": "Compare who can choose to opt out.", "people": {"leo": 3}, "themes": {"wealth": 4}, "node": "wealth", "source": "characters.leo.sections.tech", "icon": "wealth", "world": "The ability to opt out is uneven. Leo can afford to choose less everyday health tracking. Sophia’s wearable helps her save on insurance, and Ken’s tracker was issued by the Marines.", "sources": ["characters.leo.sections.tech", "characters.sophia.sections.tech", "characters.ken.sections.tech"]}]}, {"id": "community", "title": "What would you make time for after the day is done?", "options": [{"id": "garden", "title": "Learn or grow something with others", "detail": "Follow Catherine and Veronica’s gardening connection.", "people": {"catherine": 2, "veronica": 2}, "themes": {"education": 2}, "node": "gardening", "source": "characters.veronica.sections.third", "icon": "gardening", "world": "Community can form around learning and growing food. Catherine teaches online gardening classes that Veronica attends. Gardening and volunteering help both of them stay active and connected.", "sources": ["characters.veronica.sections.third", "characters.catherine.sections.third"]}, {"id": "family", "title": "Time with my family", "detail": "Follow Ken’s life as a father and Marine.", "people": {"ken": 4}, "themes": {"geography": 1}, "node": "vacation", "source": "characters.ken.sections.third", "icon": "people", "world": "Family time has to fit around work and care. Ken raises his son in on-base housing and sometimes struggles with childcare coverage. They get to the beach when they can.", "sources": ["characters.ken.sections.home", "characters.ken.sections.third"]}, {"id": "outside", "title": "Get out on the water or a trail", "detail": "Explore Leo’s recreation and who can access it.", "people": {"leo": 3}, "themes": {"wealth": 2, "climate": 1}, "node": "vacation", "source": "characters.leo.sections.third", "icon": "vacation", "world": "The outdoors is also shaped by access. Leo spends time on his boat and hikes in state-reserved and private recreation areas. His wealth gives him choices that few can readily afford.", "sources": ["characters.leo.sections.third", "characters.leo.sections.health"]}]}, {"id": "question", "title": "Which question would you want to look into first?", "options": [{"id": "access", "title": "Who can afford these choices?", "detail": "Compare care, housing, and recreation across incomes.", "people": {"sophia": 1, "ken": 1}, "themes": {"wealth": 5}, "node": "wealth", "source": "themes.wealth", "icon": "wealth", "world": "New options do not reach everyone equally. Income affects access to food, care, housing, and recreation. Comparing Leo’s choices with Ken’s and Sophia’s makes those differences visible.", "sources": ["themes.wealth", "characters.leo.sections.health", "characters.sophia.sections.home"]}, {"id": "climate", "title": "Where can people build a stable home?", "detail": "Follow climate, migration, and access to fresh water.", "people": {"ken": 2, "leo": 1}, "themes": {"climate": 5}, "node": "climate", "source": "themes.climate", "icon": "climate", "world": "Climate change puts pressure on where people can build a stable life. Ken’s childhood displacement and Leo’s choice of the Great Lakes show very different experiences of moving home.", "sources": ["themes.climate"]}, {"id": "change", "title": "What skills and connections will matter?", "detail": "Follow learning, automation, and community.", "people": {"veronica": 2}, "themes": {"education": 4, "materials": 1}, "node": "education", "source": "themes.education", "icon": "education", "world": "Skills and relationships develop through several paths. Satellite schools, technical training, military-supported degrees, and community classes all have a place in this world. Automation changes the skills people need.", "sources": ["themes.education", "truths.robotics"]}]}]};
window.FuturePresentation = {"world": {"title": "The world in 2048", "paragraphs": ["Climate change, unequal resources, and new technology shape everyday life in this possible future. People live longer, automation is common, and care and food can be more personalized. Access still varies with income and where someone lives.", "Start with an orange theme tile on the map. Read the notes beside the people, then compare their experiences with the filters. Pink cards connect shared activities; cyan circles connect the technology they use."], "sources": ["truths.global", "truths.health", "truths.robotics", "truths.elder", "themes.wealth", "themes.geography"]}, "themes": {"climate": {"title": "Climate change", "paragraphs": ["Natural disasters are becoming more frequent and more severe. People move away from disaster-prone places, disrupting housing, food supplies, and local economies. Competition over land and other resources adds to wider instability.", "These changes reach people differently. Ken left the climate-endangered Marshall Islands as a child. Leo could afford a home near the fresh water and more sustainable climate of the Great Lakes. Veronica hopes to use technology to develop plant-based diets that reduce climate harm."], "notes": {"leo": {"text": "Could afford a home in the Great Lakes climate haven.", "sources": ["themes.climate", "characters.leo.sections.home"]}, "ken": {"text": "Left the Marshall Islands as a child and fears displacement again.", "sources": ["themes.climate", "characters.ken.sections.home"]}, "veronica": {"text": "Hopes to develop plant-based renewable diets that reduce climate harm.", "sources": ["themes.climate"]}}, "sources": ["themes.climate"]}, "wealth": {"title": "Wealth gap", "paragraphs": ["Income changes the choices people can make about care, food, housing, and recreation. Leo is in the top 1%. Catherine and Veronica sit in the middle to upper-middle group, while Ken and Sophia are in the lower to lower-middle group.", "The difference is visible in everyday life. Leo can afford a mobile doctor, household staff, and private recreation, and can choose less health tracking. Sophia uses a wearable to lower insurance costs while weighing the cost of a home and a family. Ken relies on fixed military pay, on-base housing, and base food services."], "notes": {"leo": {"text": "Top 1%: private care, household staff, and more choice over tracking.", "sources": ["themes.wealth", "characters.leo.sections.health", "characters.leo.sections.home", "characters.leo.sections.tech"]}, "ken": {"text": "Fixed military pay; on-base housing and food services support his family.", "sources": ["themes.wealth", "characters.ken.sections.work", "characters.ken.sections.home", "characters.ken.sections.health"]}, "sophia": {"text": "Low to middle income; homeownership and starting a family raise cost questions.", "sources": ["characters.sophia.sections.work", "characters.sophia.sections.home"]}, "veronica": {"text": "Her middle-income parents support her; she also has an allowance.", "sources": ["characters.veronica.sections.work"]}, "catherine": {"text": "Retired with a full pension and fixed retirement income.", "sources": ["characters.catherine.sections.work"]}}, "sources": ["themes.wealth", "characters.leo.sections.health", "characters.leo.sections.home", "characters.leo.sections.tech", "characters.sophia.sections.tech", "characters.sophia.sections.home", "characters.ken.sections.work", "characters.ken.sections.home", "characters.ken.sections.health"]}, "geography": {"title": "Where you live", "paragraphs": ["Leo lives in the suburbs, Catherine and Ken in urban settings, and Veronica and Sophia in rural communities. Those settings connect people to different forms of work, education, care, and community.", "Veronica attends a local satellite schoolhouse linked to a larger school network. Sophia travels through rural Wyoming as a robotic assisted paramedic. Ken and his son live in military housing in Hawaii, while Catherine lives alone with friends and neighbors nearby. Leo chose the Great Lakes for its climate, fresh water, business location, and boating."], "notes": {"leo": {"text": "Suburb: a Great Lakes home near his business and the water.", "sources": ["themes.geography", "characters.leo.sections.home"]}, "ken": {"text": "Urban: on-base military housing in Hawaii with his son.", "sources": ["themes.geography", "characters.ken.sections.home"]}, "sophia": {"text": "Rural: rents with her partner and serves communities around Wyoming.", "sources": ["themes.geography", "characters.sophia.sections.home", "characters.sophia.sections.work"]}, "veronica": {"text": "Rural: a satellite school connects her to a wider school district.", "sources": ["themes.geography", "characters.veronica.sections.work"]}, "catherine": {"text": "Urban: lives alone and has a community of friends and neighbors.", "sources": ["themes.geography", "characters.catherine.sections.home"]}}, "sources": ["themes.geography", "characters.veronica.sections.work", "characters.sophia.sections.work", "characters.ken.sections.home", "characters.catherine.sections.home", "characters.leo.sections.home"]}, "education": {"title": "Education", "paragraphs": ["Learning follows several paths in this world. Veronica’s satellite school connects her rural community to a larger network, and her ambitions in robotics may take her beyond a traditional school-to-college route.", "Ken earned an associate’s degree through the Marine Corps. Sophia trained at a technical school and would consider more education if it made financial sense and helped her care for more people. Leo holds a BA but credits experience and entrepreneurship for his success. Catherine values nursing school as both professional preparation and a chance to learn about life away from home."], "notes": {"leo": {"text": "Holds a BA, but credits experience and entrepreneurship for his success.", "sources": ["themes.education", "characters.leo.sections.work"]}, "ken": {"text": "Earned an associate’s degree with military support.", "sources": ["themes.education", "characters.ken.sections.work"]}, "sophia": {"text": "Trained at a technical school for robotic assisted paramedicine.", "sources": ["themes.education", "characters.sophia.sections.work"]}, "veronica": {"text": "A satellite school supports her interests in robotics and technology.", "sources": ["themes.education", "characters.veronica.sections.work"]}, "catherine": {"text": "Values college and nursing school as foundations for her life’s work.", "sources": ["themes.education"]}}, "sources": ["themes.education"]}, "materials": {"title": "Regional materials", "paragraphs": ["Control over critical raw materials creates tension between Russia, China, and the United States. The world described here relies on domestic stockpiles and manufacturing, allied supply, and mining from the sea floor and space asteroids.", "Those supply systems connect directly to Ken’s work in an advanced-manufacturing materials warehouse and Leo’s autonomous trucking business. Their roles show how a global resource issue reaches the movement and storage of everyday goods."], "notes": {"leo": {"text": "His trucking company moves cargo using autonomous long-haul vehicles.", "sources": ["characters.leo.sections.work"]}, "ken": {"text": "Works in logistics at an advanced-manufacturing materials warehouse.", "sources": ["characters.ken.sections.work"]}}, "sources": ["themes.materials", "truths.global", "truths.supply", "characters.ken.sections.work", "characters.leo.sections.work"]}}};
window.FutureChatReplies = {"leo": {"intro": "I’m Leo. I run a trucking company, and my family lives near the Great Lakes. What would you like to know?", "work": {"text": "I founded Leo Trucking Company. Our long-haul trucks drive themselves, and people handle the last mile. I have a BA, but I give experience and an entrepreneurial spirit more credit for my success. I also own a nonprofit that supplies automated medical equipment to underserved communities.", "sources": ["characters.leo.sections.work"]}, "home": {"text": "My wife and I have a large mixed family, and we live near the Great Lakes. The climate, fresh water, and central location for the business all helped us choose it. We love boating, too. We have staff at home and a personal assistant who handles the day-to-day things.", "sources": ["characters.leo.sections.home"]}, "health": {"text": "Wealth is health, as I like to say. I can afford a mobile doctor, personalized healthcare, steak, and access to private places to exercise. That kind of access is a commodity few people can readily afford.", "sources": ["characters.leo.sections.health"]}, "tech": {"text": "I can afford to be less dependent on things like health-tracking wearables, and that is my choice. I still use plenty of automation. My business uses driverless cargo shipping, and drones can deliver food and goods to my boat.", "sources": ["characters.leo.sections.tech"]}, "third": {"text": "I spend as much time as I can on my boat on the nearby lakes. I also enjoy hiking in state-reserved and privately owned recreation areas near my home.", "sources": ["characters.leo.sections.third"]}}, "sophia": {"intro": "I’m Sophia. I work as a robotic assisted paramedic around rural Wyoming. You can ask about my work or what life looks like outside it.", "work": {"text": "I trained at a local technical school to become a robotic assisted paramedic. I serve rural areas in and around Wyoming. My income falls in the low-to-middle range.", "sources": ["characters.sophia.sections.work"]}, "home": {"text": "My partner and I rent our home. We hope to buy a place we can stay in for good. I’m also exploring the possibility of having a family, although I’m not sure I can afford children.", "sources": ["characters.sophia.sections.home"]}, "health": {"text": "I like locally grown and made food from the farmers market. I would love to grow more of my own if I had the time. Yoga keeps me active, and I use legalized psychedelics.", "sources": ["characters.sophia.sections.health"]}, "tech": {"text": "Robotics, automation, and technology are central to my work in healthcare. I wish I could help more people. In my own life, I have a phone, laptop, and a bio-tracker that helps me save on health insurance.", "sources": ["characters.sophia.sections.tech"]}, "third": {"text": "My community includes the farmers market, the yoga studio, and the rural area where I live. Those are my third spaces outside work and home.", "sources": ["characters.sophia.sections.third"]}}, "ken": {"intro": "I’m Ken. I’m a Marine logistics specialist and a dad. My son and I live on base in Hawaii. What would you like to ask?", "work": {"text": "I’m an enlisted logistics specialist in the Marines, working with an advanced-manufacturing materials warehouse. The military helped me earn my associate’s degree. My income is fixed military pay.", "sources": ["characters.ken.sections.work"]}, "home": {"text": "My five-year-old son and I live in military housing on base in Hawaii. I take being his father seriously, and my service helps give us a foundation. Childcare coverage can be difficult. I left the Marshall Islands as a child, so the thought of being displaced again worries me.", "sources": ["characters.ken.sections.home"]}, "health": {"text": "We try to eat well, but convenience matters when I’m looking after my son. We rely on base food services and supplement them with fast food.", "sources": ["characters.ken.sections.health"]}, "tech": {"text": "Technology is at the center of most of my logistics work. Personally, I have a phone, a computer, and a bio-tracker issued by the Marines.", "sources": ["characters.ken.sections.tech"]}, "third": {"text": "There isn’t much time for a third space when you’re a single dad in the service. We get to the beach whenever we can. That’s where I met Leo when he was on vacation in Hawaii.", "sources": ["characters.ken.sections.third"]}}, "veronica": {"intro": "I’m Veronica. I’m in seventh grade, and I’m into soccer, gardening, robotics, and gaming. What do you want to explore?", "work": {"text": "I attend a small satellite schoolhouse connected virtually to the wider school district. That lets me learn in a rural area while using the resources of a bigger district. My parents support me, and I also have an allowance.", "sources": ["characters.veronica.sections.work"]}, "home": {"text": "I live in a stable home about 90 minutes from a major city. I have friends I see in person and friends I meet virtually. I look up to science advocates and hope to work on plant-based renewable diets someday.", "sources": ["characters.veronica.sections.home"]}, "health": {"text": "I eat vegetables from our garden and meals delivered around my family’s nutritional needs. Soccer, gardening, robotics, gaming, and volunteering are some of my hobbies.", "sources": ["characters.veronica.sections.health"]}, "tech": {"text": "I use a bio-tracker, phone, tablet, and computer, along with smart in-home health and virtual community tools. I also use VR for entertainment and gaming.", "sources": ["characters.veronica.sections.tech"]}, "third": {"text": "I play soccer, spend time with friends online and in person, and take Catherine’s online gardening classes. I also volunteer for Leo’s nonprofit, which brings medical robotics and technology to underserved communities.", "sources": ["characters.veronica.sections.third"]}}, "catherine": {"intro": "I’m Catherine. I’m a retired nurse, and gardening and volunteering are important parts of my life now. What would you like to talk about?", "work": {"text": "I’m retired after more than 20 years as a registered nurse. I have a full pension and fixed retirement income through my 401K.", "sources": ["characters.catherine.sections.work"]}, "home": {"text": "I lost my husband to COVID and now live alone. I worry about who will care for me as I get older. Friends and neighbors have helped me find a community.", "sources": ["characters.catherine.sections.home"]}, "health": {"text": "I grow vegetables in my outdoor garden and a smaller one indoors. I also get personalized meals based on my nutritional needs. Gardening and volunteering keep me active and fulfilled. My hearing is waning, and I have had a knee replacement.", "sources": ["characters.catherine.sections.health"]}, "tech": {"text": "My wearable is tied to my healthcare. I also use a virtual AI assistant, smart in-home health, virtual community tools, and VR for travel and entertainment.", "sources": ["characters.catherine.sections.tech"]}, "third": {"text": "I spend time with lifelong friends nearby and have made more connections with younger people in the community. I enjoy community gardening, volunteering, virtual travel, VR entertainment, and time with the local community.", "sources": ["characters.catherine.sections.third"]}}};